// https://emojibase.dev version 17.0.0

const b4a = require('b4a')
const { hostToLE32, hostToLE16 } = require('convert-endianness')

const INDEX = b4a.from('', 'base64')

exports.EMOJI_COUNT = 1949
exports.SKIN_COUNT = 475
exports.GROUP_COUNT = 10

exports.EMOJI_RECORDS = to32(0, 46776)
exports.SKIN_RECORDS = to32(46776, 52476)
exports.EMOTICONS = to32(52476, 52732)
exports.GROUPS = to32(52732, 52812)
exports.POINT_PALETTE = to32(52812, 58616)
exports.POINT_INDICES = to16(58616, 72240)
exports.SC_OFFSETS = to16(72240, 78672)
exports.SC_STRINGS = INDEX.subarray(78672, 119368)
exports.STRINGS = INDEX.subarray(119368, 145437)

function to32 (offset, end) {
  const arr = new Uint32Array(INDEX.buffer, offset, (end - offset) / 4)
  hostToLE32(arr)
  return arr
}
function to16 (offset, end) {
  const arr = new Uint16Array(INDEX.buffer, offset, (end - offset) / 2)
  hostToLE16(arr)
  return arr
}
